CREATE TABLE rm_ownership_source_snapshots (id INTEGER PRIMARY KEY, snapshot_id TEXT NOT NULL UNIQUE CHECK(length(snapshot_id) BETWEEN 3 AND 80), source TEXT NOT NULL CHECK(length(source) BETWEEN 1 AND 160), observed_at TEXT NOT NULL, snapshot_hash TEXT NOT NULL CHECK(length(snapshot_hash)=64 AND snapshot_hash NOT GLOB '*[^0-9a-f]*'), diff_hash TEXT NOT NULL CHECK(length(diff_hash)=64 AND diff_hash NOT GLOB '*[^0-9a-f]*'), canonical_facts TEXT NOT NULL CHECK(length(canonical_facts) BETWEEN 2 AND 1048576), diff_json TEXT NOT NULL CHECK(length(diff_json) BETWEEN 2 AND 1048576), actor TEXT NOT NULL CHECK(length(actor) BETWEEN 3 AND 160), principal_kind TEXT NOT NULL CHECK(principal_kind IN ('user','service_account','local_operator')), principal_id TEXT NOT NULL CHECK(length(principal_id) BETWEEN 1 AND 160), created_at TEXT NOT NULL);
CREATE TABLE rm_ownership_snapshot_events (id INTEGER PRIMARY KEY, snapshot_id TEXT NOT NULL REFERENCES rm_ownership_source_snapshots(snapshot_id), event_type TEXT NOT NULL CHECK(event_type IN ('proposed','approved','rejected','applied')), actor TEXT NOT NULL CHECK(length(actor) BETWEEN 3 AND 160), principal_kind TEXT NOT NULL CHECK(principal_kind IN ('user','service_account','local_operator')), principal_id TEXT NOT NULL CHECK(length(principal_id) BETWEEN 1 AND 160), created_at TEXT NOT NULL);
CREATE UNIQUE INDEX rm_ownership_snapshot_event_once ON rm_ownership_snapshot_events(snapshot_id,event_type);
CREATE TABLE rm_ownership_facts (id INTEGER PRIMARY KEY, fact_id TEXT NOT NULL UNIQUE CHECK(length(fact_id) BETWEEN 3 AND 80), snapshot_id TEXT NOT NULL REFERENCES rm_ownership_source_snapshots(snapshot_id), fact_hash TEXT NOT NULL UNIQUE CHECK(length(fact_hash)=64 AND fact_hash NOT GLOB '*[^0-9a-f]*'), canonical_fact TEXT NOT NULL CHECK(length(canonical_fact) BETWEEN 2 AND 32768), owner_kind TEXT NOT NULL CHECK(owner_kind IN ('company','party')), owner_id TEXT NOT NULL CHECK(length(owner_id) BETWEEN 1 AND 120), owned_company_slug TEXT NOT NULL CHECK(length(owned_company_slug) BETWEEN 1 AND 120), valid_from TEXT NOT NULL, valid_to_exclusive TEXT, economic_exact_bp INTEGER, economic_min_bp INTEGER, economic_max_bp INTEGER, voting_bp INTEGER, control_type TEXT NOT NULL CHECK(control_type IN ('equity','voting','board','agreement','other')), share_class TEXT, jurisdiction TEXT NOT NULL CHECK(length(jurisdiction)=2), review_state TEXT NOT NULL CHECK(review_state='approved'), created_at TEXT NOT NULL, CHECK((economic_exact_bp IS NOT NULL AND economic_min_bp IS NULL AND economic_max_bp IS NULL) OR (economic_exact_bp IS NULL AND economic_min_bp IS NOT NULL AND economic_max_bp IS NOT NULL AND economic_min_bp<=economic_max_bp)), CHECK(valid_to_exclusive IS NULL OR valid_to_exclusive>valid_from));
CREATE INDEX rm_ownership_facts_asof ON rm_ownership_facts(owned_company_slug,valid_from,valid_to_exclusive);
CREATE TRIGGER rm_ownership_source_snapshots_no_update BEFORE UPDATE ON rm_ownership_source_snapshots BEGIN SELECT RAISE(ABORT, 'ownership snapshots are append-only'); END;
CREATE TRIGGER rm_ownership_source_snapshots_no_delete BEFORE DELETE ON rm_ownership_source_snapshots BEGIN SELECT RAISE(ABORT, 'ownership snapshots are append-only'); END;
CREATE TRIGGER rm_ownership_snapshot_events_no_update BEFORE UPDATE ON rm_ownership_snapshot_events BEGIN SELECT RAISE(ABORT, 'ownership snapshot events are append-only'); END;
CREATE TRIGGER rm_ownership_snapshot_events_no_delete BEFORE DELETE ON rm_ownership_snapshot_events BEGIN SELECT RAISE(ABORT, 'ownership snapshot events are append-only'); END;
CREATE TRIGGER rm_ownership_facts_no_update BEFORE UPDATE ON rm_ownership_facts BEGIN SELECT RAISE(ABORT, 'ownership facts are append-only'); END;
CREATE TRIGGER rm_ownership_facts_no_delete BEFORE DELETE ON rm_ownership_facts BEGIN SELECT RAISE(ABORT, 'ownership facts are append-only'); END;
